#!/usr/bin/env bash
# ON THE GPU BOX, from the repository root (rsynced). Builds outside the lock; every stage below takes ~/.gpu.lock itself (one hold per stage,
# the stage's correctness gates and timing inside it), with a per-stage timeout.
#   bench/exec_vs_torch/box_job.sh OUT_DIR           env: REPS (7), LOCK_WAIT (s), STAGES ("mlp_runs mlp_steps mlp_size diag flags gpt")
# GPT workloads (gen.py) are expected as w_tiny / w_small / w_162m_1 in the repository root; MLP bundles are generated by the drivers.
set -uo pipefail
OUT="${1:?OUT_DIR}"; REPS="${REPS:-7}"; ARCH="${KVM_ARCH:-sm_80}"; STAGES="${STAGES:-mlp_runs mlp_steps mlp_size diag flags gpt}"
export PATH=$PATH:/usr/local/cuda/bin
mkdir -p "$OUT/logs"
FL="-O3 -arch=$ARCH -std=c++17 -Iinclude --fmad=false -Xcompiler -ffp-contract=off -diag-suppress 177"
[ -x ./kvm_exec ] || nvcc $FL kvm_exec.cu -o kvm_exec > "$OUT/logs/build.txt" 2>&1
{ date -u +%FT%TZ; nvidia-smi --query-gpu=name,driver_version,clocks.max.sm --format=csv,noheader; nvcc --version | tail -1
  python3 -c "import torch,triton;print('torch',torch.__version__,'cuda',torch.version.cuda,'triton',triton.__version__,'sms',torch.cuda.get_device_properties(0).multi_processor_count)"
  echo "commit: ${KVM_COMMIT:-$(git rev-parse --short HEAD 2>/dev/null)}"; echo "flags: $FL"; } > "$OUT/env.txt" 2>&1
M="python3 -I bench/exec_vs_torch/run_mlp.py"
run() { local name="$1"; shift; echo "=== $name $(date -u +%T)"; flock -w "${LOCK_WAIT:-28800}" ~/.gpu.lock timeout "${STAGE_TIMEOUT:-3000}" "$@" > "$OUT/logs/$name.txt" 2>&1; echo "exit $? $name" | tee -a "$OUT/logs/status.txt"; }
for s in $STAGES; do case "$s" in
  mlp_runs)   run mlp_runs   $M "$OUT/work_h72" --exe ./kvm_exec --hidden 72 --depth 2 --steps 50 --runs 1,2,4,8,16,32 --reps "$REPS" --out "$OUT/mlp_runs.json" ;;
  mlp_steps)  for n in 10 200 1000; do
                run mlp_steps_$n $M "$OUT/work_h72" --exe ./kvm_exec --hidden 72 --depth 2 --steps $n --runs 1,8 --reps "$REPS" --out "$OUT/mlp_steps_$n.json"; done ;;
  mlp_size)   for c in 256:4 1024:2; do h=${c%%:*}; d=${c##*:}
                run mlp_size_$h $M "$OUT/work_h${h}_d$d" --exe ./kvm_exec --hidden $h --depth $d --no-golden --steps 50 --runs 1,8 --reps "$REPS" --out "$OUT/mlp_size_$h.json"; done ;;
  flags)      W="$OUT/work_h72"   # admission windowing: default flags (streamed ~1000-task records) vs the whole tape as one record
              for r in 1 8 32; do for k in 1 2 3; do
                run flags_r${r}_$k bash -c "echo default; ./kvm_exec --quiet $W/time_n50_r$r; echo onerecord; ./kvm_exec --quiet --max-tasks 262144 --live-cap 131072 --ring-words 8388608 $W/time_n50_r$r"; done; done ;;
  diag)       W="$OUT/work_h72"; F="--max-tasks 262144 --live-cap 131072 --ring-words 8388608"
              run diag_r1 bash -c "./kvm_exec $F --trace-csv $OUT/trace_r1.csv $W/steps50/bundle; python3 -I bench/vs_pytorch/trace_summary.py $OUT/trace_r1.csv 50"
              run diag_r32 bash -c "./kvm_exec $F --trace-csv $OUT/trace_r32.csv $W/time_n50_r32; python3 -I bench/vs_pytorch/trace_summary.py $OUT/trace_r32.csv 50" ;;
  gpt)        for w in tiny small; do
                run gpt_$w python3 -I bench/exec_vs_torch/run_gpt.py w_$w --exe ./kvm_exec --reps "$REPS" --tol 2e-3 --out "$OUT/gpt_$w.json"; done
              run gpt_162m python3 -I bench/exec_vs_torch/run_gpt.py w_162m_3 --exe ./kvm_exec --modes eager,graph,compile_graph --reps 5 --tol 1e-3 --out "$OUT/gpt_162m.json" ;;
esac; done
echo done >> "$OUT/logs/status.txt"
